"""Model card / backtest report (Markdown), regenerated by every `ei forecast run`.

Influenza positivity (M5) and dengue incidence (D4) share the selection, backtest and
coverage tables; the dengue card adds the with/without-weather comparison."""

from __future__ import annotations

from datetime import UTC, datetime
from pathlib import Path

import numpy as np
import pandas as pd

from ei_db.catalog import MODEL_LABELS, feature_label
from ei_pipeline.forecasting import config as cfg
from ei_pipeline.forecasting.spec import TargetSpec, influenza

NAMES = MODEL_LABELS
#: Bootstrap resamples (over origins) for the weather comparison.
BOOTSTRAP = 2000
BOOTSTRAP_SEED = 7


def _fmt(metric: str, v, target: str = "positivity") -> str:
    if v is None or pd.isna(v):
        return "—"
    if metric in ("mae", "rmse"):
        return f"{v * 100:.2f} pp" if target == "positivity" else f"{v:.2f}"
    if metric in ("skill_vs_snaive", "coverage_80", "coverage_95"):
        return f"{v:+.1%}" if metric == "skill_vs_snaive" else f"{v:.1%}"
    return f"{v:.3f}"


def _intro(spec: TargetSpec, summary: dict) -> list[str]:
    horizons = ", ".join(str(h) for h in cfg.HORIZONS)
    if spec.target == "positivity":
        return [
            "# Model card — influenza test positivity forecasts", "", _stamp(summary), "",
            "## What is forecast", "",
            f"Weekly influenza **test positivity** (positives ÷ specimens, WHO FluNet) for "
            f"{summary['countries']} countries in coverage tiers "
            f"{', '.join(cfg.ELIGIBLE_TIERS)}, {horizons} weeks after the latest settled "
            "week. One pooled model per horizon (direct strategy), trained on the logit of "
            "smoothed positivity. Not a case count and not a clinical risk estimate.", ""]
    return [
        "# Model card — dengue incidence forecasts", "", _stamp(summary), "",
        "## What is forecast", "",
        f"Weekly reported **dengue incidence** (cases per 100,000 population; WHO Global "
        f"Dengue Surveillance and World Bank population) for {summary['countries']} weekly-"
        f"reporting countries in dengue coverage tiers A and B, {horizons} weeks after the "
        "latest settled week. One pooled model per horizon (direct strategy), trained on "
        "log(incidence + one case per 100,000 population), with tree models learning the "
        "change from this week. Case definitions differ between countries (suspected, "
        "probable or confirmed), so a forecast describes a country's own reporting, not "
        "comparable infection rates. Errors below are in cases per 100,000 per week.", ""]


def _stamp(summary: dict) -> str:
    return (f"_Generated by `ei forecast run` on {datetime.now(UTC):%Y-%m-%d %H:%M} UTC · "
            f"run `{summary['run_key']}` · reference week {summary['reference_week']}._")


def write_model_card(path: Path, summary: dict, evals: pd.DataFrame, selection, shap_out,
                     panel, bt: pd.DataFrame | None = None,
                     spec: TargetSpec | None = None) -> None:
    spec = spec or influenza()
    pooled = evals[evals["iso3"].isna()]
    lines = _intro(spec, summary) + [
        "## Selection",
        "",
        "| Horizon | Active model | Why |",
        "|---|---|---|",
    ]
    for h, s in sorted(selection.items()):
        lines.append(f"| {h} week{'s' if h > 1 else ''} | {NAMES[s.active]} | {s.note} |")

    unit = "percentage points (pp) of positivity" if spec.target == "positivity" else \
        "cases per 100,000 per week"
    volume = "testing-volume" if spec.target == "positivity" else "case-count"
    lines += ["", "## Backtest", "",
              f"Rolling origin, expanding window: origins every {cfg.ORIGIN_STEP} weeks from "
              f"{cfg.BACKTEST_START} to the reference week minus the horizon; ML models refitted "
              f"every {cfg.REFIT_EVERY} weeks on targets known at the refit origin. All models "
              f"are scored on the same country-weeks. Errors in {unit}. Intervals: sequential "
              "split conformal (normalised by 8-week volatility, calibrated per "
              f"{volume} group on earlier origins only; first "
              f"{cfg.CONFORMAL_MIN_ORIGINS} origins have none).", ""]
    for h in sorted(pooled["horizon"].unique()):
        t = pooled[pooled["horizon"] == h].pivot_table(index="model", columns="metric",
                                                       values="value", aggfunc="first")
        n = pooled[pooled["horizon"] == h][["model", "n_obs", "n_origins"]].drop_duplicates("model")
        t = t.join(n.set_index("model")).sort_values("mase")
        lines += [f"### {h}-week horizon", "",
                  "| Model | MAE | RMSE | MASE | Skill vs seasonal naive | 80% coverage | "
                  "95% coverage | Cases | Origins |",
                  "|---|---|---|---|---|---|---|---|---|"]
        for model, r in t.iterrows():
            active = " **(active)**" if selection[h].active == model else ""
            lines.append(
                f"| {NAMES[model]}{active} | {_fmt('mae', r.get('mae'), spec.target)} | "
                f"{_fmt('rmse', r.get('rmse'), spec.target)} | {_fmt('mase', r.get('mase'))} | "
                f"{_fmt('skill_vs_snaive', r.get('skill_vs_snaive'))} | "
                f"{_fmt('coverage_80', r.get('coverage_80'))} | "
                f"{_fmt('coverage_95', r.get('coverage_95'))} | {int(r['n_obs'])} | "
                f"{int(r['n_origins'])} |")
        lines.append("")

    if bt is not None:
        if any(m.endswith("_weather") for m in spec.ml_models):
            lines += weather_section(bt, selection, summary.get("weather_coverage"))
        lines += _coverage_by_group(bt, selection, spec)

    scale = ("logit" if spec.target == "positivity" else
             "log(incidence + one case per 100,000); change from this week")
    lines += ["## Most influential features", "",
              f"Mean |SHAP| over the latest forecasts ({scale} scale), tree models.", ""]
    for (name, h), (values, _, _, features) in sorted(shap_out.items()):
        if h != cfg.HORIZONS[0]:
            continue
        imp = pd.Series(abs(values).mean(axis=0), index=features).sort_values(
            ascending=False).head(6)
        lines.append(f"- **{NAMES[name]}, {h}-week:** " + ", ".join(
            f"{feature_label(f, spec.target)} ({v:.2f})" for f, v in imp.items()))
    lines += ["", "## Data and limitations", "", *_limitations(spec), ""]
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines), encoding="utf-8")


def _limitations(spec: TargetSpec) -> list[str]:
    if spec.target == "positivity":
        return [
            f"- Training targets from {cfg.TRAIN_START}; target weeks in the COVID-19 window "
            f"({cfg.COVID_START} → {cfg.COVID_END}), provisional weeks and weeks with fewer "
            f"than {cfg.MIN_TESTS} specimens are excluded.",
            "- The backtest uses today's (revised) data, not data as first published, so "
            "real-time accuracy can be lower, especially at the 1-week horizon.",
            "- Positivity depends on who is tested; changes in testing practice shift it.",
            "- Spatial features: transmission-zone average and the mean of spatial neighbours "
            "among modelled countries (queen contiguity, else 4 nearest). Countries without a "
            "boundary polygon (GLP, GUF, MTQ) have no neighbour features.",
            "- Forecasts are produced only for countries with a valid positivity in the "
            "reference week.",
        ]
    return [
        f"- Training targets from {cfg.TRAIN_START}; provisional weeks are excluded. "
        "COVID-19 weeks are kept (dengue transmission and reporting continued).",
        "- Half of the modelled countries report weekly to WHO only from 2023–2024, so "
        "their history is short; seasonal-naive needs a year of history and rows without it "
        "are not scored.",
        "- Weekly reporters without a World Bank population (Guadeloupe, Martinique, Wallis "
        "and Futuna) have no incidence and are not modelled; monthly reporters are not "
        "forecast (their months are not split into invented weeks).",
        "- The backtest uses today's (revised) data, not data as first published; recent "
        "dengue weeks are often revised upwards, so real-time accuracy can be lower.",
        "- Weather is ERA5 at one point per country (docs/datasets/weather.md); large or "
        "climatically varied countries are poorly represented by it.",
        "- Neighbour features use spatial neighbours among the modelled countries; island "
        "areas without a boundary have none.",
    ]


def weather_comparison(bt: pd.DataFrame, seed: int = BOOTSTRAP_SEED,
                       n_boot: int = BOOTSTRAP) -> pd.DataFrame:
    """Per horizon and algorithm: MAE without and with weather on the same rows, the
    relative change, and a 95% bootstrap interval of the change resampling origins
    (rows of one origin share weather and outbreaks, so they are not independent)."""
    rng = np.random.default_rng(seed)
    out = []
    for algo in sorted({m.removesuffix("_weather") for m in bt["model"]
                        if m.endswith("_weather")}):
        for h, hb in bt.groupby("horizon"):
            a = hb[hb["model"] == algo].set_index(["iso3", "origin"])
            b = hb[hb["model"] == f"{algo}_weather"].set_index(["iso3", "origin"])
            j = a[["point", "actual_p"]].join(b[["point"]], rsuffix="_w", how="inner")
            if j.empty:
                continue
            e0 = (j["point"] - j["actual_p"]).abs()
            e1 = (j["point_w"] - j["actual_p"]).abs()
            by_origin = pd.DataFrame({"e0": e0, "e1": e1}).groupby(level="origin").sum()
            sums = by_origin.to_numpy()
            idx = rng.integers(0, len(sums), (n_boot, len(sums)))
            boot = sums[idx].sum(axis=1)
            rel = boot[:, 1] / boot[:, 0] - 1
            per_country = pd.DataFrame({"e0": e0, "e1": e1}).groupby(level="iso3").mean()
            out.append({
                "algorithm": algo, "horizon": h, "cases": len(j),
                "origins": len(by_origin), "mae": e0.mean(), "mae_weather": e1.mean(),
                "change": e1.mean() / e0.mean() - 1,
                "ci_low": float(np.quantile(rel, 0.025)),
                "ci_high": float(np.quantile(rel, 0.975)),
                "countries_better": int((per_country["e1"] < per_country["e0"]).sum()),
                "countries": len(per_country),
            })
    return pd.DataFrame(out)


def weather_verdict(row) -> str:
    if row["ci_high"] < 0:
        return "weather helps"
    if row["ci_low"] > 0:
        return "weather hurts"
    return "no clear difference"


def weather_section(bt: pd.DataFrame, selection, coverage: dict | None) -> list[str]:
    cmp_ = weather_comparison(bt)
    lines = ["## Does weather help?", "",
             "Each tree model is fitted twice on the same rows and origins: with the base "
             "features only, and with 18 ERA5 weather features added (4-week mean "
             "temperature, total precipitation and mean humidity ending 4, 8 and 12 weeks "
             "before the origin, and their anomalies from the country's 2013–2022 normal). "
             "Change = MAE with weather ÷ MAE without − 1 (negative = weather lowers the "
             f"error). 95% interval: bootstrap over origins ({BOOTSTRAP} resamples). A weather "
             "model is used only if it wins the backtest selection above.", ""]
    if coverage:
        lines += [f"Weather coverage: {coverage['rows_with_weather']:.0%} of backtest rows "
                  f"and {coverage['countries_at_origin']} of {coverage['countries']} countries "
                  "at the latest origin have weather features (missing weather is left "
                  "missing; tree models handle the gaps).", ""]
    if cmp_.empty:
        return [*lines, "No comparable rows.", ""]
    lines += ["| Horizon | Model | MAE without | MAE with weather | Change | 95% interval | "
              "Countries improved | Verdict |", "|---|---|---|---|---|---|---|---|"]
    for r in cmp_.sort_values(["horizon", "algorithm"]).to_dict("records"):
        lines.append(
            f"| {r['horizon']} | {NAMES[r['algorithm']]} | {r['mae']:.2f} | "
            f"{r['mae_weather']:.2f} | {r['change']:+.1%} | {r['ci_low']:+.1%} to "
            f"{r['ci_high']:+.1%} | {r['countries_better']} of {r['countries']} | "
            f"{weather_verdict(r)} |")
    used = sorted(h for h, s in selection.items() if s.active.endswith("_weather"))
    lines += ["", "**Result:** " + (
        f"the active model uses weather at the {', '.join(map(str, used))}-week "
        f"horizon{'s' if len(used) > 1 else ''}." if used else
        "the active models do not use weather: no weather model both won the selection and "
        "showed a clear benefit over its twin without weather."), ""]
    return lines


def _coverage_by_group(bt: pd.DataFrame, selection, spec: TargetSpec) -> list[str]:
    edges = spec.volume_edges
    names = ([f"< {edges[0]}"] + [f"{a}–{b}" for a, b in zip(edges, edges[1:], strict=False)]
             + [f"≥ {edges[-1]}"])
    noun = "testing volume" if spec.target == "positivity" else "reported cases"
    what = "Specimens" if spec.target == "positivity" else "Reported cases"
    width_unit = "pp" if spec.target == "positivity" else "per 100k"
    lines = [f"### Interval coverage by {noun} (active models)", "",
             f"{what} per week (4-week mean at the origin). Quantiles are calibrated per group "
             "(Mondrian conformal), so noise in low-volume countries does not widen the "
             "intervals of high-volume countries.", "",
             f"| Horizon | {spec.volume_label} | 80% coverage | 95% coverage | Median 80% width | "
             "Median 95% width | Cases |", "|---|---|---|---|---|---|---|"]
    mult = 100 if spec.target == "positivity" else 1
    for h, sel in sorted(selection.items()):
        a = bt[(bt["model"] == sel.active) & (bt["horizon"] == h)].dropna(subset=["lo80"])
        for g, gg in a.groupby("volume_group"):
            c80 = gg["actual_p"].between(gg["lo80"], gg["hi80"]).mean()
            c95 = gg["actual_p"].between(gg["lo95"], gg["hi95"]).mean()
            w80 = (gg["hi80"] - gg["lo80"]).median() * mult
            w95 = (gg["hi95"] - gg["lo95"]).median() * mult
            lines.append(f"| {h} | {names[int(g)]} | {c80:.1%} | {c95:.1%} | {w80:.1f} "
                         f"{width_unit} | {w95:.1f} {width_unit} | {len(gg)} |")
    return [*lines, ""]
